{"code": "import zipfile
import os

# Check the files
files = ['data/train.csv.zip', 'data/test.csv.zip']
for filepath in files:
    print(f"\n--- Checking {filepath} ---")
    print(f"File size: {os.path.getsize(filepath)} bytes")
    try:
        with zipfile.ZipFile(filepath, 'r') as z:
            print(f"Valid zip file. Contents: {z.namelist()}")
    except Exception as e:
        print(f"Error opening as zip: {e}")
        # Try reading as plain text
        try:
            with open(filepath, 'rb') as f:
                header = f.read(20)
                print(f"First 20 bytes (hex): {header.hex()}")
                print(f"First 20 bytes (text): {header}")
        except Exception as e2:
            print(f"Error reading file: {e2}")"}

